using System.IO.Compression;
using System.Text.Json;
using System.Globalization;
namespace StarlightSyndicateDemo;
public sealed record DogmaValue45(bool Known,double Value,string Origin);
public sealed record DogmaResult45(bool Supported,double? Value,string Reason,string[] Trace);
public static class Dogma45
{
 static string Root=>Path.Combine(AppContext.BaseDirectory,"Assets","Dogma45");
 static JsonElement Read(string file){using var s=File.OpenRead(Path.Combine(Root,file));using var g=new GZipStream(s,CompressionMode.Decompress);using var d=JsonDocument.Parse(g);return d.RootElement.Clone();}
 static readonly Lazy<JsonElement> Index=new(()=>Read("index.json.gz"));
 static readonly Dictionary<int,JsonElement> Buckets=[];static readonly Queue<int> Order=[];static readonly object Gate=new();
 public static JsonElement? Record(string dataset,int id)=>Index.Value.TryGetProperty(dataset,out var set)&&set.TryGetProperty(id.ToString(),out var record)?record:null;
 public static JsonElement? Type(int id){lock(Gate){int bucket=id/1000;if(!Buckets.TryGetValue(bucket,out var data)){string f=$"types/{bucket}.json.gz";if(!File.Exists(Path.Combine(Root,f)))return null;data=Read(f);Buckets[bucket]=data;Order.Enqueue(bucket);while(Order.Count>4)Buckets.Remove(Order.Dequeue());}return data.TryGetProperty(id.ToString(),out var row)?row:null;}}
 public static int CachedBuckets{get{lock(Gate)return Buckets.Count;}}
 public static DogmaValue45 Attribute(int type,int attribute){var r=Type(type);if(r.HasValue&&r.Value.TryGetProperty("dogmaAttributes",out var a))foreach(var p in a.EnumerateArray())if(p.GetProperty("attributeID").GetInt32()==attribute)return new(true,p.GetProperty("value").GetDouble(),"Explicit type value");var d=Record("dogmaAttributes",attribute);if(d.HasValue&&d.Value.TryGetProperty("defaultValue",out var v)&&v.TryGetDouble(out double n))return new(true,n,"Declared attribute default");return new(false,0,"Unknown attribute; no default");}
 public static double Weight(int rank){if(rank<0)throw new ArgumentOutOfRangeException(nameof(rank));return Math.Exp(-Math.Pow(rank/2.22292081,2));}
 // Keep legacy single-precision behavior and clamps: this is the shared live combat owner.
 public static float CombatStack(IEnumerable<float> strengths,bool increase=false){float result=1;int rank=0;foreach(float s in strengths.OrderByDescending(Math.Abs)){if(!float.IsFinite(s))throw new ArgumentException("Nonfinite stacking input");float weight=MathF.Exp(-MathF.Pow(rank++/2.22292081f,2));result*=1+(increase?1:-1)*Math.Clamp(s,0,.99f)*weight;}return Math.Clamp(result,.01f,20);}
 public static DogmaResult45 Operation(double current,double modifier,int operation){if(!double.IsFinite(current)||!double.IsFinite(modifier))return new(false,null,"Nonfinite operand",[]);double? n=operation switch{-1 or 7=>modifier,0 or 4=>current*modifier,1 or 5=>modifier==0?null:current/modifier,2=>current+modifier,3=>current-modifier,6=>current*(1+modifier/100),_=>null};return n.HasValue&&double.IsFinite(n.Value)?new(true,n,"Calculated",[$"{current:R} op {operation} {modifier:R} = {n:R}"]):new(false,null,"Unsupported operation, zero divisor, or overflow",[]);}
 // Preview one attribute only; no mutation of live ships. Reject the entire effect if scope is unsupported.
 public static DogmaResult45 Preview(int effect,int targetAttribute,int targetType,int ownerType,string domain){var row=Record("dogmaEffects",effect);if(!row.HasValue||!row.Value.GetProperty("PreviewSupported").GetBoolean())return new(false,null,row?.GetProperty("Reason").GetString()??"Unknown effect",[]);var b=Attribute(targetType,targetAttribute);if(!b.Known)return new(false,null,b.Origin,[]);double result=b.Value;var trace=new List<string>{b.Origin+": "+result.ToString("R",CultureInfo.InvariantCulture)};bool found=false;foreach(var m in row.Value.GetProperty("Source").GetProperty("modifierInfo").EnumerateArray()){if(m.GetProperty("modifiedAttributeID").GetInt32()!=targetAttribute)continue;found=true;if(m.GetProperty("domain").GetString()!=domain)return new(false,null,"Explicit context does not match source domain",trace.ToArray());var operand=Attribute(ownerType,m.GetProperty("modifyingAttributeID").GetInt32());if(!operand.Known)return new(false,null,operand.Origin,trace.ToArray());var next=Operation(result,operand.Value,m.GetProperty("operation").GetInt32());if(!next.Supported)return next;result=next.Value!.Value;trace.AddRange(next.Trace);}return found?new(true,result,"Isolated preview; not a complete fit or activated effect",trace.ToArray()):new(false,null,"Effect does not modify requested attribute",trace.ToArray());}
 public static DogmaResult45 SystemBuffPreview(int beaconType,int shipType,int attribute){var effect=Record("systemWideEffects",beaconType);if(!effect.HasValue)return new(false,null,"Unknown system effect",[]);if(effect.Value.TryGetProperty("eligibleTypeListID",out var list)&&!UnifiedCatalog40.InTypeList(list.GetInt32(),shipType))return new(false,null,"Ship is excluded by source type list",[]);if(!effect.Value.TryGetProperty("dbuffs",out var buffs))return new(false,null,"Non-dbuff system effect unsupported",[]);var b=Attribute(shipType,attribute);if(!b.Known)return new(false,null,b.Origin,[]);double result=b.Value;var trace=new List<string>();bool found=false;foreach(var item in buffs.EnumerateArray()){int id=item.GetProperty("_key").GetInt32();var definition=Record("dbuffCollections",id);if(!definition.HasValue)return new(false,null,"Unknown dbuff collection",[]);var d=definition.Value;if(new[]{"locationModifiers","locationGroupModifiers","locationRequiredSkillModifiers"}.Any(k=>d.TryGetProperty(k,out var a)&&a.GetArrayLength()>0))return new(false,null,"Dbuff requires unsupported location scope",[]);if(!d.TryGetProperty("itemModifiers",out var modifiers))return new(false,null,"No numeric item modifiers",[]);if(!modifiers.EnumerateArray().Any(m=>m.GetProperty("dogmaAttributeID").GetInt32()==attribute))continue;found=true;int op=d.GetProperty("operationName").GetString() switch{"PostPercent"=>6,"ModAdd"=>2,"PreAssignment"=>-1,"PostAssignment"=>7,"PostMul"=>4,_=>999};var next=Operation(result,item.GetProperty("_value").GetDouble(),op);if(!next.Supported)return next;result=next.Value!.Value;trace.AddRange(next.Trace);}return found?new(true,result,"Single emitter preview; collection aggregation and live activation pending",trace.ToArray()):new(false,null,"No matching numeric dbuff attribute",[]);}
 public static DogmaResult45 FighterCooldown(int fighterType,int slot,bool highSec,bool lowSec){var fighter=Record("fighterAbilitiesByType",fighterType);if(!fighter.HasValue||slot<0||slot>2)return new(false,null,"Unknown fighter or slot",[]);if(!fighter.Value.TryGetProperty("abilitySlot"+slot,out var a))return new(false,null,"Empty ability slot",[]);var def=Record("fighterAbilities",a.GetProperty("abilityID").GetInt32());if(!def.HasValue)return new(false,null,"Unknown ability",[]);if((highSec&&def.Value.GetProperty("disallowInHighSec").GetBoolean())||(lowSec&&def.Value.GetProperty("disallowInLowSec").GetBoolean()))return new(false,null,"Source security restriction",[]);return a.TryGetProperty("cooldownSeconds",out var cooldown)?new(true,cooldown.GetDouble(),"Source cooldown; ability behavior remains catalog owned",[]):new(false,null,"Source cooldown absent; not assumed zero",[]);}
 public static string Format(double n,int unit)=>unit switch{0=>n.ToString("0.###",CultureInfo.InvariantCulture),101=>(n/1000).ToString("0.###",CultureInfo.InvariantCulture)+" s",122=>n.ToString("0.###",CultureInfo.InvariantCulture)+" slots",105=>n.ToString("0.###",CultureInfo.InvariantCulture)+"%",108=>(100*(1-n)).ToString("0.###",CultureInfo.InvariantCulture)+"%",109=>(100*(n-1)).ToString("+0.###;-0.###;0",CultureInfo.InvariantCulture)+"%",111=>(100*(1-n)).ToString("0.###",CultureInfo.InvariantCulture)+"%",_=>n.ToString("0.###",CultureInfo.InvariantCulture)+(Record("dogmaUnits",unit) is {} u&&u.TryGetProperty("displayName",out var d)&&d.TryGetProperty("en",out var en)?" "+en.GetString():$" [unit {unit}]")};
 public static DogmaResult45 Mutation(int mutator,int inputType,int attribute,double roll){var r=Record("dynamicItemAttributes",mutator);if(!r.HasValue||!double.IsFinite(roll)||roll<0||roll>1)return new(false,null,"Unknown mutator or roll outside [0,1]",[]);bool eligible=r.Value.GetProperty("inputOutputMapping").EnumerateArray().Any(m=>m.GetProperty("applicableTypes").EnumerateArray().Any(t=>t.GetInt32()==inputType));if(!eligible)return new(false,null,"Input type not eligible",[]);foreach(var a in r.Value.GetProperty("attributeIDs").EnumerateArray())if(a.GetProperty("_key").GetInt32()==attribute){var b=Attribute(inputType,attribute);if(!b.Known)return new(false,null,b.Origin,[]);double factor=a.GetProperty("min").GetDouble()+(a.GetProperty("max").GetDouble()-a.GetProperty("min").GetDouble())*roll;return new(true,b.Value*factor,"Range preview; no item created",[$"Base {b.Value:R}; multiplier {factor:R}"]);}return new(false,null,"Attribute not mutable",[]);}
 public static bool InProximity(double distance,double radius,double elapsed,double delay)=>double.IsFinite(distance)&&double.IsFinite(radius)&&double.IsFinite(elapsed)&&double.IsFinite(delay)&&distance>=0&&radius>=0&&elapsed>=0&&delay>=0&&distance<=radius&&elapsed>=delay;
 public static InformationEntry? Information(string key){if(!key.StartsWith("dogma45/"))return null;string[] parts=key.Split('/');if(parts.Length!=3||!int.TryParse(parts[2],out int id))return null;var row=Record(parts[1],id);if(!row.HasValue)return null;var e=new InformationEntry{Key=key,Id=id.ToString(),Name="Mechanics record "+id,Kind="Mechanics",Group="Source mechanics / "+parts[1],Description="Imported mechanics reference. Source records are not automatically activated."};e.Add("Description",e.Description);if(parts[1]=="dogmaEffects"){e.Add("Support","Live execution","Inactive: existing catalog owns gameplay");e.Add("Support","Isolated numeric preview",row.Value.GetProperty("PreviewSupported").GetBoolean()?"Supported with explicit context":"Unsupported");e.Add("Support","Reason",row.Value.GetProperty("Reason").GetString()!);}foreach(var p in row.Value.EnumerateObject())e.Add("Source audit",p.Name,p.Value.ToString());return e;}
 public static InformationEntry Attach(InformationEntry original,int type){if(type<=0||Type(type) is not {} row)return original;var e=new InformationEntry{Key=original.Key,Id=original.Id,Name=original.Name,Kind=original.Kind,Group=original.Group,Description=original.Description,MarketId=original.MarketId,System=original.System,LastSeen=original.LastSeen,Tabs=original.Tabs.ToDictionary(p=>p.Key,p=>p.Value.ToList()),Stats=new(original.Stats),Related=original.Related.ToList()};if(e.Tabs.ContainsKey("Mechanics"))return e;e.Add("Mechanics","Gameplay owner","Existing fitted catalogs; raw effects never applied a second time");e.Add("Mechanics","Source build","3569502");e.Add("Mechanics","Values","Explicit source base attributes; fitted values are on Attributes / Fitting");if(row.TryGetProperty("dogmaAttributes",out var attrs))foreach(var a in attrs.EnumerateArray()){int id=a.GetProperty("attributeID").GetInt32();var def=Record("dogmaAttributes",id);string label=ShipAttributeCatalog.All.FirstOrDefault(x=>x.ReferenceId==id)?.Label??"Attribute "+id;int unit=def.HasValue&&def.Value.TryGetProperty("unitID",out var u)?u.GetInt32():0;e.Add("Mechanics",label,Format(a.GetProperty("value").GetDouble(),unit),$"dogma45/dogmaAttributes/{id}");}if(row.TryGetProperty("dogmaEffects",out var effects))foreach(var a in effects.EnumerateArray()){int id=a.GetProperty("effectID").GetInt32();var status=Record("dogmaEffects",id);e.Add("Mechanics","Effect "+id,status.HasValue&&status.Value.GetProperty("PreviewSupported").GetBoolean()?"Preview supported / live inactive":"Reference / live inactive",$"dogma45/dogmaEffects/{id}");}foreach(string set in new[]{"typeBonus","dynamicItemAttributes","fighterAbilitiesByType","appliedProximityEffects","linkWithShip","proximityTrap","systemDbuffEmitters","systemWideEffects"})if(Record(set,type).HasValue)e.Add("Mechanics",set,"Imported reference; activation pending",$"dogma45/{set}/{type}");return e;}
}
